#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define PARSE_OPT_SHARP         0x00000001
#define PARSE_OPT_BKSLASH       0x00000002
#define PARSE_OPT_SQUOTE        0x00000004
#define PARSE_OPT_DQUOTE        0x00000008
#define PARSE_OPT_ENV           0x00000010
#define PARSE_OPT_INPLACE       0x00000020

#define PARSE_ERR_TOOLARGE      0x00000001
#define PARSE_ERR_TOOMANY       0x00000002
#define PARSE_ERR_QUOTE         0x00000004
#define PARSE_ERR_BRACE         0x00000008
#define PARSE_ERR_HEX           0x00000010
#define PARSE_ERR_VARNAME       0x00000020
#define PARSE_ERR_OVERLAP       0x00000040

int ishex(char s)
{
        s -= '0';
        if ((unsigned char)s <= 9)
                return 1;
        s -= 'A' - '0';
        if ((unsigned char)s <= 5)
                return 1;
        s -= 'a' - 'A';
        if ((unsigned char)s <= 5)
                return 1;
        return 0;
}

#define EMIT_CHAR(x)                                                   \
        do {                                                           \
                char __c = (char)(x);                                  \
                if ((opts & PARSE_OPT_INPLACE) && out+outpos > in)     \
                        err |= PARSE_ERR_OVERLAP;                      \
                if (outpos >= outmax)                                  \
                        err |= PARSE_ERR_TOOLARGE;                     \
                if (!err)                                              \
                        out[outpos] = __c;                             \
                outpos++;                                              \
        } while (0)

uint32_t parse_line(char *in, char *out, size_t *outlen, char **args, int *nbargs, uint32_t opts, char **errptr)
{
        char *quote = NULL;
        char *brace = NULL;
        unsigned char hex1, hex2;
        size_t outmax = *outlen;
        int argsmax = *nbargs;
        size_t outpos = 0;
        int squote = 0;
        int dquote = 0;
        int arg = 0;
        uint32_t err = 0;

        *nbargs = 0;
        *outlen = 0;

        args[arg] = out;
        while (1) {
                if (*in >= '-' && *in != '\\') {
                        EMIT_CHAR(*in++);
                        continue;
                }
                else if (*in == '\0' || *in == '\n' || *in == '\r') {
                        break;
                }
                else if (*in == '#' && (opts & PARSE_OPT_SHARP) && !squote && !dquote) {
                        break;
                }
                else if (*in == '"' && !squote && (opts & PARSE_OPT_DQUOTE)) {
                        if (dquote) {
                                dquote = 0;
                                quote = NULL;
                        }
                        else {
                                dquote = 1;
                                quote = in;
                        }
                        in++;
                        continue;
                }
                else if (*in == '\'' && !dquote && (opts & PARSE_OPT_SQUOTE)) {
                        if (squote) {
                                squote = 0;
                                quote = NULL;
                        }
                        else {
                                squote = 1;
                                quote = in;
                        }
                        in++;
                        continue;
                }
                else if (*in == '\\' && !squote && (opts & PARSE_OPT_BKSLASH)) {
                        char tosend = *in;

                        switch (in[1]) {
                        case ' ':
                        case '\\':
                                tosend = in[1];
                                in++;
                                break;

                        case 't':
                                tosend = '\t';
                                in++;
                                break;

                        case 'n':
                                tosend = '\n';
                                in++;
                                break;

                        case 'r':
                                tosend = '\r';
                                in++;
                                break;

                        case '#':
                                if (opts & PARSE_OPT_SHARP)
                                        in++;
                                tosend = *in;
                                break;

                        case '\'':
                                if (opts & PARSE_OPT_SQUOTE && !squote)
                                        in++;
                                tosend = *in;
                                break;

                        case '"':
                                if (opts & PARSE_OPT_DQUOTE && !squote)
                                        in++;
                                tosend = *in;
                                break;

                        case '$':
                                if (opts & PARSE_OPT_ENV && dquote)
                                        in++;
                                tosend = *in;
                                break;

                        case 'x':
                                if (!ishex(in[2]) || !ishex(in[3])) {
                                        err |= PARSE_ERR_HEX;
                                        if (errptr)
                                                *errptr = in;
                                        goto leave;
                                }
                                hex1 = toupper(in[2]) - '0';
                                hex2 = toupper(in[3]) - '0';
                                if (hex1 > 9) hex1 -= 'A' - '9' - 1;
                                if (hex2 > 9) hex2 -= 'A' - '9' - 1;
                                tosend = (hex1 << 4) + hex2;
                                in += 3;
                                break;

                        default:
                                break;
                        }

                        in++;
                        EMIT_CHAR(tosend);
                }
                else if (isspace((unsigned char)*in) && !squote && !dquote) {
                        while (isspace((unsigned char)*in))
                                in++;
                        EMIT_CHAR(0);
                        arg++;
                        if (arg < argsmax)
                                args[arg] = out + outpos;
                        else
                                err |= PARSE_ERR_TOOMANY;
                }
                else if (*in == '$' && (opts & PARSE_OPT_ENV) && (dquote || !(opts & PARSE_OPT_DQUOTE))) {
                        char *var_name;
                        char save_char;
                        char *value;

                        in++;

                        if (*in == '{')
                                brace = in++;

                        if (!isalpha((unsigned char)*in) && *in != '_') {
                                err |= PARSE_ERR_VARNAME;
                                if (errptr)
                                        *errptr = in;
                                goto leave;
                        }

                        var_name = in;
                        while (isalnum((unsigned char)*in) || *in == '_')
                                in++;

                        save_char = *in;
                        *in = '\0';
                        value = getenv(var_name);
                        *in = save_char;

                        if (brace) {
                                if (*in != '}') {
                                        err |= PARSE_ERR_BRACE;
                                        if (errptr)
                                                *errptr = brace;
                                        goto leave;
                                }
                                in++;
                                brace = NULL;
                        }

                        if (value) {
                                while (*value)
                                        EMIT_CHAR(*value++);
                        }
                }
                else {
                        EMIT_CHAR(*in++);
                }
        }

        EMIT_CHAR(0);
        arg++;

        if (quote) {
                err |= PARSE_ERR_QUOTE;
                if (errptr)
                        *errptr = quote;
                goto leave;
        }
 leave:
        *nbargs = arg;
        *outlen = outpos;

        while (arg < argsmax)
                args[arg++] = out + outpos - 1;

        return err;
}
#undef EMIT_CHAR

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <file>\n", argv[0]); return 1; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = 0;
    fclose(f);

    char *out = malloc(sz + 1);
    char *args[64];
    size_t outlen = sz + 1;
    int nbargs = 64;
    char *errptr = NULL;
    uint32_t err = parse_line(buf, out, &outlen, args, &nbargs,
        PARSE_OPT_ENV | PARSE_OPT_DQUOTE | PARSE_OPT_SQUOTE | PARSE_OPT_BKSLASH | PARSE_OPT_SHARP, &errptr);
    printf("err=%u nbargs=%d outlen=%zu\n", err, nbargs, outlen);
    return 0;
}
